import{G as e,K as t,at as n,n as r}from"./chunks/framework.CZI4dhmU.js";var i=JSON.parse(`{"title":"软件版本","description":"","frontmatter":{},"headers":[],"relativePath":"knowledge/version.md","filePath":"knowledge/version.md"}`),a={name:`knowledge/version.md`};function o(r,i,a,o,s,c){return n(),e(`div`,null,[...i[0]||=[t(`<h1 id="软件版本" tabindex="-1">软件版本 <a class="header-anchor" href="#软件版本" aria-label="Permalink to “软件版本”">​</a></h1><ul><li>一个软件在不同时期的版本叫法。</li></ul><h2 id="开发中" tabindex="-1">开发中 <a class="header-anchor" href="#开发中" aria-label="Permalink to “开发中”">​</a></h2><h3 id="alpha-版本-内侧版本" tabindex="-1">Alpha 版本 (内侧版本) <a class="header-anchor" href="#alpha-版本-内侧版本" aria-label="Permalink to “Alpha 版本 (内侧版本)”">​</a></h3><ul><li><p>Alpha 版本仍然需要测试，其功能亦未完善，因为它是整个软件发布周期中的第一个阶段，所以它的名称是“Alpha”，希腊字母中的第一个字母“α”。</p></li><li><p>Alpha 版本通常会送到开发软件的组织或某群体中的软件测试者作内部测试。在市场上，越来越多公司会邀请外部客户或合作伙伴参与其测试。这令软件在此阶段有更大的可用性测试</p></li></ul><h3 id="beta-版本-公测版本" tabindex="-1">Beta 版本 （公测版本） <a class="header-anchor" href="#beta-版本-公测版本" aria-label="Permalink to “Beta 版本 （公测版本）”">​</a></h3><ul><li>Beta 版本是软件最早对外公开的软件版本，由公众（通常为公司外的第三方开发者和业余玩家）参与测试。 因为是 Alpha 的下一个阶段，所以为希腊字母的第二个字 Beta (β)。</li><li>一般来说，Beta 包含所有功能，但可能有一些已知问题和较轻微的程序错误（BUG），要进行调试（debug）。</li><li>Beta 版本的测试者通常是开发软件的组织的客户，他们会以免费或优惠价钱得到软件。</li><li>Beta 版本亦作为测试产品的支持和市场反应等。</li></ul><h3 id="rc-版本-候选版本" tabindex="-1">RC 版本 （候选版本） <a class="header-anchor" href="#rc-版本-候选版本" aria-label="Permalink to “RC 版本 （候选版本）”">​</a></h3><ul><li>Release Candidate（简称 RC）指可能成为最终产品的候选版本，如果未出现问题则可发布成为正式版本。在此阶段的产品通常包含所有功能、或接近完整，亦不会出现严重问题。</li></ul><h2 id="正式版本" tabindex="-1">正式版本 <a class="header-anchor" href="#正式版本" aria-label="Permalink to “正式版本”">​</a></h2><h3 id="ga-版本" tabindex="-1">GA 版本 <a class="header-anchor" href="#ga-版本" aria-label="Permalink to “GA 版本”">​</a></h3><ul><li>正式版本，也叫 GA 版本，此版本已经上线了正式运营了。</li><li>此版本会持续维护，修复 bug，完善功能等。</li></ul><h3 id="stable-版本" tabindex="-1">Stable 版本 <a class="header-anchor" href="#stable-版本" aria-label="Permalink to “Stable 版本”">​</a></h3><ul><li>稳定版本，也叫 Stable 版本，是软件的稳定版本，一般会在软件发布周期的最后一个阶段发布。</li><li>此版本基本不会发生改变，只是修复一些 bug。</li></ul>`,14)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};